  if (o->encoding == OBJ_ENCODING_LISTPACK ||
    o->encoding == OBJ_ENCODING_LISTPACK_EX) {
    *vstr = NULL;
    res = hashTypeGetFromListpack(o, field, vstr, vlen, vll, expiredAt);

