void backgroundRewriteDoneHandler(int exitcode, int bysignal) {
  int rewrite_success = 0;
  char bgrewrite_error[256] = "";

  if (!bysignal && exitcode == 0) {
    char tmpfile[256];
    long long now = ustime();
    sds new_base_filepath = NULL;
    sds new_incr_filepath = NULL;
    aofManifest *temp_am;
    mstime_t latency;

