void sentinelCheckObjectivelyDown(sentinelRedisInstance *master) {
  dictIterator di;
  dictEntry *de;
  unsigned int quorum = 0, odown = 0;

  if (master->flags & SRI_S_DOWN) {
    /* Is down for enough sentinels? */
    quorum = 1; /* the current sentinel. */
